import { Component, inject, linkedSignal, signal } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';
import { RatesPanel } from '../rates/rates';

// The one screen: sign in by name, then choose a sheet by id.
@Component({
  selector: 'app-home',
  imports: [People, RatesPanel],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form (submit)="load($event)">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetInput()"
          (input)="sheetInput.set($any($event.target).value); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-error">{{ err }}</p>
        }
      </form>

      @if (session.loading()) {
        <p role="status">Loading the sheet…</p>
      } @else if (session.sheetId(); as id) {
        <p>Sheet <strong data-testid="sheet-current-id">{{ id }}</strong></p>
        <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>

        <form (submit)="saveToday($event)">
          <label for="sheet-today">Change today</label>
          <input
            id="sheet-today"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set($any($event.target).value); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Save</button>
          @if (todayError(); as err) {
            <p role="alert" data-testid="sheet-today-error">{{ err }}</p>
          }
        </form>

        <app-rates />
        <app-people />
      }
    } @else {
      <form (submit)="signIn($event)">
        <label for="signin-name">Your name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set($any($event.target).value); signinError.set(null)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError(); as err) {
          <p role="alert" data-testid="signin-error">{{ err }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayInput = linkedSignal(() => this.session.today() ?? '');
  protected readonly todayError = signal<string | null>(null);
  /** Set while a change of today awaits the store, so a second submit does not store it twice. */
  private savingToday = false;

  protected signIn(event: Event): void {
    event.preventDefault();
    const name = this.nameInput().trim();
    if (!name) {
      this.signinError.set('Enter your name.');
      return;
    }
    this.signinError.set(null);
    this.session.signIn(name);
  }

  protected async load(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Enter a sheet id.');
      return;
    }
    try {
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set('The sheet could not be loaded.');
    }
  }

  protected async saveToday(event: Event): Promise<void> {
    event.preventDefault();
    if (this.savingToday) return;
    this.todayError.set(null);
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.todayError.set('Enter a date as yyyy-mm-dd.');
      return;
    }
    this.savingToday = true;
    try {
      await this.session.setToday(today);
    } catch {
      this.todayError.set('That date could not be saved.');
    } finally {
      this.savingToday = false;
    }
  }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one record for a change to a sheet: the event, then sheet=&lt;id&gt; and by=&lt;user&gt;, then
     * the fields, separated by single spaces. Inside a transaction the record is written only once
     * it commits, so a change that is refused or rolled back writes nothing.
     */
    public void change(String event, String sheetId, String user, String... fields) {
        StringBuilder entry = new StringBuilder(event).append(" sheet=").append(sheetId).append(" by=").append(user);
        for (String field : fields) {
            entry.append(' ').append(field);
        }
        String line = entry.toString();
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCommit() {
                    record(line);
                }
            });
        } else {
            record(line);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL.
for i in $(seq 1 60); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then break; fi
  sleep 1
done

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )

